/**
 * Set the physics tick rate in Hz.
 * Must be called before init() to take effect.
 * @param {number} hz - Tick rate in Hz (e.g., 100 for low fidelity, 625 for default)
 */
export function setTickRate(hz: number): void;
/**
 * Increment BVH test counter (called from trimeshCollide).
 */
export function incrementBvhTests(): void;
/**
 * Increment BVH hit counter (called from trimeshCollide).
 */
export function incrementBvhHits(): void;
/**
 * Set the physics update interval in milliseconds.
 * Must be called before init() to take effect.
 * @param {number} intervalMs - Interval in milliseconds (e.g., 16.67 for 60 FPS)
 */
export function setPhysicsInterval(intervalMs: number): void;
/**
 * Set the solver iterations for Dynamic ↔ Dynamic collision resolution.
 * More iterations = more stable stacking but slower performance.
 * Can be called at any time (takes effect immediately).
 * @param {number} velocityIterations - Number of velocity solver iterations (default: 4, like RAPIER)
 * @param {number} [positionIterations=2] - Number of position correction iterations
 */
export function setSolverIterations(velocityIterations: number, positionIterations?: number): void;
/**
 * Initialize the physics loop.
 * @param {Function} [cb] - Optional callback for each frame
 * @returns {string} Status message
 */
export function init(cb?: Function): string;
/**
 * Stop the physics loop.
 * @returns {string} Status message
 */
export function stop(): string;
/**
 * Execute a physics step (main loop iteration).
 * @param {Function} [cb] - Optional callback
 * @param {number} counter - Frame counter
 */
export function step(cb?: Function, counter: number): void;
/**
 * Step to read input from the front (main thread).
 * @param {Function} [cb] - Optional callback
 * @param {number} counter - Frame counter
 */
export function stepReadFront(cb?: Function, counter: number): void;
export let bvhTests: number;
export let bvhHits: number;
